#!/usr/bin/env python3\n\"\"\"\nTwitch Streamer for T3MPLATE TV WORLD\nFFmpeg RTMP push from renderer or emulator output.\n\"\"\"\n\nimport os\nimport subprocess\nfrom pathlib import Path\nfrom app.config import CONFIG\n\nclass TwitchStreamer:\n    def __init__(self):\n        self.key = os.getenv('TWITCH_STREAM_KEY')\n        self.rtmp_url = f\"rtmp://live.twitch.tv/app/{self.key}\" if self.key else None\n        self.process = None\n\n    def start_stream_from_api(self, input_url: str = \"http://localhost:8080/video_feed\"):\n        \"\"\"Stream from station API video endpoint.\"\"\"\n        if not self.rtmp_url:\n            return \"No TWITCH_STREAM_KEY set in .env\"\n        \n        cmd = [\n            'ffmpeg',\n            '-re',  # Read input at native frame rate\n            '-i', input_url,\n            '-c:v', 'libx264',\n            '-preset', 'fast',\n            '-crf', '23',\n            '-c:a', 'aac',\n            '-b:a', '128k',\n            '-f', 'flv',\n            self.rtmp_url\n        ]\n        self.process = subprocess.Popen(cmd)\n        return f\"Streaming to {self.rtmp_url} (PID: {self.process.pid})\"\n\n    def start_stream_from_retroarch(self, retroarch_window_title: str = \"RetroArch\"):\n        \"\"\"OBS-style, but direct FFmpeg capture (requires win grab).\"\"\"\n        # For Windows: Use gdigrab for window capture\n        cmd = [\n            'ffmpeg',\n            '-f', 'gdigrab',\n            '-i', 'title=RetroArch',\n            '-f', 'dshow',  # Audio from default\n            '-i', 'audio=\"Microphone (Realtek Audio)\"',\n            '-c:v', 'libx264',\n            '-preset', 'ultrafast',\n            '-f', 'flv',\n            self.rtmp_url\n        ]\n        self.process = subprocess.Popen(cmd)\n        return f\"Capturing RetroArch to Twitch\"\n\n    def stop_stream(self):\n        if self.process:\n            self.process.terminate()\n            self.process = None\n            return \"Stream stopped\"\n        return \"No active stream\"\n\nif __name__ == \"__main__\":\n    streamer = TwitchStreamer()\n    print(streamer.start_stream_from_api())\n
